import{_ as i,o as n,c as t,a2 as e}from"./chunks/framework.DBU8LMUS.js";const p=JSON.parse('{"title":"Peringkat Kontribusi","description":"","frontmatter":{"title":"Peringkat Kontribusi","version":"1.0.0","last_updated":"2026-08-10T00:00:00.000Z","pdf_export":true},"headers":[],"relativePath":"latest/peringkat.md","filePath":"latest/peringkat.md","lastUpdated":1786334463000}'),r={name:"latest/peringkat.md"};function s(o,a,l,k,u,m){return n(),t("div",null,[...a[0]||(a[0]=[e('<h1 id="peringkat-kontribusi" tabindex="-1">Peringkat Kontribusi <a class="header-anchor" href="#peringkat-kontribusi" aria-label="Permalink to &quot;Peringkat Kontribusi&quot;">​</a></h1><h2 id="pendahuluan" tabindex="-1">Pendahuluan <a class="header-anchor" href="#pendahuluan" aria-label="Permalink to &quot;Pendahuluan&quot;">​</a></h2><p><strong>Peringkat Kontribusi</strong> menampilkan urutan anggota berdasarkan <strong>skor kontribusi</strong> (<code>contribution_score</code>). Skor ini mencerminkan keaktifan dan kontribusi anggota terhadap komunitas, misalnya melalui kegiatan, mentoring, dan bentuk partisipasi lainnya.</p><h2 id="membuka-peringkat" tabindex="-1">Membuka Peringkat <a class="header-anchor" href="#membuka-peringkat" aria-label="Permalink to &quot;Membuka Peringkat&quot;">​</a></h2><ol><li>Klik menu <strong>Peringkat</strong> pada navigasi.</li><li>Halaman menampilkan daftar anggota yang diurutkan dari skor tertinggi ke terendah.</li></ol><h2 id="informasi-yang-ditampilkan" tabindex="-1">Informasi yang Ditampilkan <a class="header-anchor" href="#informasi-yang-ditampilkan" aria-label="Permalink to &quot;Informasi yang Ditampilkan&quot;">​</a></h2><p>Setiap baris pada peringkat menampilkan:</p><ul><li><strong>Posisi/ranking</strong> anggota.</li><li><strong>Nama</strong> anggota.</li><li><strong>Skor kontribusi</strong>.</li><li>(Jika tersedia) capaian atau pencapaian anggota.</li></ul><h2 id="memahami-skor-kontribusi" tabindex="-1">Memahami Skor Kontribusi <a class="header-anchor" href="#memahami-skor-kontribusi" aria-label="Permalink to &quot;Memahami Skor Kontribusi&quot;">​</a></h2><p>Skor kontribusi diperbarui berdasarkan aktivitas positif anggota di platform, seperti:</p><ul><li>Berpartisipasi dalam kegiatan komunitas.</li><li>Menjadi mentor atau membantu sesama alumni.</li><li>Berperan aktif dalam grup dan forum diskusi.</li><li>Berkontribusi pada pengumuman, polling, atau galeri.</li></ul><div class="tip custom-block"><p class="custom-block-title">Catatan</p><p>Skor dihitung otomatis oleh sistem. Tidak ada cara untuk menambah skor secara instan selain terus berpartisipasi secara wajar.</p></div><h2 id="tips-meningkatkan-kontribusi" tabindex="-1">Tips Meningkatkan Kontribusi <a class="header-anchor" href="#tips-meningkatkan-kontribusi" aria-label="Permalink to &quot;Tips Meningkatkan Kontribusi&quot;">​</a></h2><ul><li>Lengkapi profil Anda secara menyeluruh.</li><li>Bergabunglah dengan grup yang sesuai minat dan ikut berdiskusi.</li><li>Daftar sebagai mentor jika Anda memiliki pengalaman untuk dibagikan.</li><li>Ikuti polling dan kegiatan yang diselenggarakan komunitas.</li></ul><p>Lanjutkan ke <a href="/webapps/latest/moderasi">Melaporkan Konten</a> untuk memahami cara menjaga kenyamanan komunitas.</p>',15)])])}const d=i(r,[["render",s]]);export{p as __pageData,d as default};
